#pragma once
#include "../App/HostedInputRecovery.h"
#include "../App/WorkspaceStore.h"
#include <fstream>

namespace coincide {
inline int hosted_input_recovery_tests(const std::filesystem::path& report){
    using namespace background_host;unsigned checks{};const auto check=[&](bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);};const auto rejects=[&](const auto& action,const char* why){bool rejected{};try{action();}catch(...){rejected=true;}check(rejected,why);};
    const auto root=std::filesystem::temp_directory_path()/winrt::to_hstring("Coincide-Input-Recovery-"+new_guid()).c_str();bool owned{};
    struct Cleanup{std::filesystem::path root;bool& owned;~Cleanup(){if(owned){std::error_code ignored;std::filesystem::remove_all(root,ignored);}}}cleanup{root,owned};
    try{
        if(!std::filesystem::create_directory(root))throw std::runtime_error("Owned recovery fixture root unavailable");owned=true;
        const auto data=root/L"queued";std::filesystem::create_directory(data);WorkspaceStore first(data);auto workspace=first.open();Thread seed;seed.id=new_guid();seed.provider="codex";seed.title="Owned recovery";const auto epoch=new_guid();seed.host_cursors.push_back({"codex",epoch,0});workspace.add_thread(seed);workspace.requires_background_host=true;first.load_thread(workspace.thread(seed.id));auto& thread=workspace.thread(seed.id);
        const auto original_id=new_guid(),other_id=new_guid();QueuedInput original{original_id,"Original queue — नमस्ते\nKeep every byte.","original-model","high","priority",true,false,{{"C:\\owned-fixture\\猫.png","猫.png","image/png"},{"C:\\owned-fixture\\notes.txt","notes.txt","text/plain"}}};
        thread.queued_inputs={original,{other_id,"Other saved input","other-model","low","",false,false,{}}};thread.draft="New draft must stay";thread.draft_attachments={{"C:\\owned-fixture\\draft.txt","draft.txt","text/plain"}};thread.model="live-model";thread.sessions.push_back({"codex","original-session",0,"default",std::string(64,'a')});first.save_thread(thread);first.save_index(workspace);
        auto scope=std::make_shared<Scope>(data);HostedClientState journal(scope);journal.open();Key key{seed.id,"codex"};HostedClientBinding binding{epoch,std::string(64,'f'),"default",std::string(64,'a')};journal.begin_generation(key,binding,{{{epoch,0},true,true},true});journal.prepare_intent(key,original_id,HostedIntentOperation::queue);journal.record_host_status(key,original_id,"accepted");journal.record_queue_removal(key,original_id,true);
        HostedClientState reopened(scope);reopened.open();const auto saved=reopened.terminal_recovery_inputs(key).front();auto plan=HostedInputRecovery::plan(thread,saved);
        check(plan.available()&&plan.remove_queued&&plan.preview.find("नमस्ते")!=std::string::npos,"Exact queued input must produce an available owner review without reading files");
        const auto rows_before=thread.messages.size();rejects([&]{HostedInputRecovery::apply(thread,plan,false);},"A recovery plan cannot modify a conversation without explicit owner choice");check(thread.messages.size()==rows_before&&thread.queued_inputs.size()==2,"Declining recovery must preserve every pending input");
        for(unsigned variant=0;variant<4;++variant){auto changed=thread;if(variant==0)changed.queued_inputs.front().text="changed text";else if(variant==1)changed.queued_inputs.front().model="changed-model";else if(variant==2)changed.queued_inputs.front().attachments.front().path="C:\\owned-fixture\\changed.png";else changed.queued_inputs.front().full_access=true;const auto before=changed.queued_inputs.front().text;rejects([&]{HostedInputRecovery::apply(changed,plan,true);},"Edited text/model/attachments/access must invalidate the exact reviewed source fingerprint");check(changed.messages.empty()&&changed.queued_inputs.size()==2&&changed.queued_inputs.front().text==before,"A stale recovery plan must fail without partial in-memory mutation");}
        auto wrong=thread;wrong.provider="claude";rejects([&]{HostedInputRecovery::plan(wrong,saved);},"Recovery must not follow a conversation into another provider");wrong=thread;wrong.host_cursors.front().epoch=new_guid();rejects([&]{HostedInputRecovery::plan(wrong,saved);},"Recovery must not cross a saved host epoch");wrong=thread;auto duplicate=original;duplicate.id=original_id.substr(1,36);wrong.queued_inputs.push_back(duplicate);rejects([&]{HostedInputRecovery::plan(wrong,saved);},"Aliases of one delivery ID must not make payload selection ambiguous");auto uncertain=saved;uncertain.disposition=HostedIntentDisposition::uncertain;rejects([&]{HostedInputRecovery::plan(thread,uncertain);},"Unknown/uncertain outcomes cannot use definite input recovery");
        const auto effect=HostedInputRecovery::apply(thread,plan,true);check(effect.queue_changed&&effect.rows.size()==2&&thread.queued_inputs.size()==1&&thread.queued_inputs.front().id==other_id,"Owner recovery may remove only its exact old future queue entry");
        check(thread.messages.size()==2&&thread.messages.front().role=="tool"&&thread.messages.front().text.find(original.text)!=std::string::npos&&thread.messages.front().text.find("original-model")!=std::string::npos,"The original queue text/settings must become historical reference before erasure");
        check(thread.messages.front().attachments.size()==2&&thread.messages.front().attachments[0].path==original.attachments[0].path&&thread.messages.front().attachments[1].name=="notes.txt","Queue attachments must remain attached to the retained reference");check(thread.draft=="New draft must stay"&&thread.draft_attachments.size()==1&&thread.model=="live-model"&&thread.sessions.front().id=="original-session","Recovery must preserve the next draft, attachments, model and provider history");
        auto collision=thread;collision.queued_inputs.push_back(original);collision.queued_inputs.back().text="different bytes";rejects([&]{HostedInputRecovery::plan(collision,saved);},"A mismatched prior reference cannot authorize dropping a different queued payload");
        const auto before_index=local_file::read(data/L"workspace.json",4*1024*1024).bytes;first.save_thread(thread);
        {Handle lock(CreateFileW((data/L"workspace.json").c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr));check(static_cast<bool>(lock),"Owned index failure lock must open");rejects([&]{first.save_index(workspace);},"Index failure must not be mistaken for two-file recovery durability");rejects([&]{reopened.retire_recovered_not_delivered(saved,{{epoch,0},true,false},true,plan.retention);},"Transcript-only recovery must not retire its original metadata");}
        check(local_file::read(data/L"workspace.json",4*1024*1024).bytes==before_index&&reopened.get(key)->pending.size()==1,"Index failure must retain both the original journal and its unchanged index");
        WorkspaceStore second(data);auto loaded=second.open();second.load_thread(loaded.thread(seed.id));auto& restored=loaded.thread(seed.id);HostedClientState after_crash(scope);after_crash.open();check(restored.queued_inputs.size()==1&&restored.messages.size()==2&&after_crash.terminal_recovery_inputs(key).size()==1,"Crash/reopen must retain the staged reference and pending definite metadata");
        auto retry=HostedInputRecovery::plan(restored,after_crash.terminal_recovery_inputs(key).front());check(retry.available(),"A retained exact-ID historical row must remain a valid original source after crash");const auto retry_effect=HostedInputRecovery::apply(restored,retry,true);check(retry_effect.rows.empty()&&restored.messages.size()==2,"Owner retry must not duplicate retained data or the same recovery decision");
        {Handle lock(CreateFileW((data/L"threads"/winrt::to_hstring(seed.id+".json").c_str()).c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr));check(static_cast<bool>(lock),"Owned transcript failure lock must open");rejects([&]{second.save_thread(restored);},"Transcript replacement failure must preserve the staged historical reference");rejects([&]{after_crash.retire_recovered_not_delivered(saved,{{epoch,0},false,true},true,retry.retention);},"Index-only recovery cannot retire a pending definite input");}
        second.save_thread(restored);second.save_index(loaded);check(after_crash.retire_recovered_not_delivered(saved,{{epoch,0},true,true},true,retry.retention)&&after_crash.get(key)->pending.empty(),"Only actual successful thread/index persistence may unblock the definite journal");
        WorkspaceStore third(data);auto durable=third.open();third.load_thread(durable.thread(seed.id));check(durable.thread(seed.id).messages.size()==2&&durable.thread(seed.id).queued_inputs.front().id==other_id&&durable.thread(seed.id).draft=="New draft must stay","The retained payload and unrelated saved work must survive a final real-file reopen");
        SessionInfo stopped{key,epoch,false,false,false,0,0,{}};stopped.profile_id=binding.profile_id;stopped.account_scope=binding.account_scope;stopped.launch_fingerprint=binding.launch_fingerprint;check(after_crash.retire_generation(key,stopped,{{epoch,0},true,true}),"The recovered definite entry must no longer permanently block a proved stopped generation");
        for(unsigned variant=0;variant<2;++variant){const auto folder=root/(variant?L"missing":L"direct");std::filesystem::create_directory(folder);WorkspaceStore store(folder);auto ws=store.open();Thread value;value.id=new_guid();value.provider="codex";value.title="Owned direct recovery";const auto generation=new_guid(),delivery=new_guid();value.host_cursors.push_back({"codex",generation,0});ws.add_thread(value);ws.requires_background_host=true;store.load_thread(ws.thread(value.id));auto& item=ws.thread(value.id);item.draft="Unrelated next draft";if(!variant)item.messages.push_back({delivery,"user","Original direct input","codex",{{"C:\\owned-fixture\\direct.png","direct.png","image/png"}}});store.save_thread(item);store.save_index(ws);auto selected=std::make_shared<Scope>(folder);HostedClientState state(selected);state.open();Key owner{value.id,"codex"};HostedClientBinding initial{generation,std::string(64,'b'),"default",{}};state.begin_generation(owner,initial,{{{generation,0},true,true},true});state.prepare_intent(owner,delivery,HostedIntentOperation::send);if(variant)state.record_not_submitted(owner,delivery);else state.record_host_status(owner,delivery,"rejected");HostedClientState crashed(selected);crashed.open();const auto reference=crashed.terminal_recovery_inputs(owner).front();const auto decision=HostedInputRecovery::plan(item,reference);check(decision.available()==!variant,"Only an exact saved source, never a current draft, proves original input availability");const auto user_count=item.messages.size();HostedInputRecovery::apply(item,decision,true);check(item.draft=="Unrelated next draft"&&item.queued_inputs.empty(),"Direct or missing-source recovery must create no new input/draft/outbox payload");check(item.messages.size()==user_count+1&&item.messages.back().role=="tool"&&(!variant||item.messages.back().text.find("could not be located")!=std::string::npos),"An explicit preserved/missing decision must be visible without fabricating original input text");if(!variant)check(item.messages.front().role=="user"&&item.messages.front().text=="Original direct input"&&item.messages.front().attachments.size()==1,"The original direct user message must remain unchanged");store.save_thread(item);store.save_index(ws);check(crashed.retire_recovered_not_delivered(reference,{{generation,0},true,true},true,decision.retention)&&crashed.get(owner)->pending.empty(),"Explicit direct/missing decisions require actual two-file persistence before retirement");}
        std::ofstream output(report);output<<"PASS: "<<checks<<" saved input preservation/recovery checks; real isolated Store/journal files, no runtime/host/provider calls\n";return output?0:2;
    }catch(const winrt::hresult_error& error){std::ofstream(report)<<"FAIL after "<<checks<<": "<<winrt::to_string(error.message())<<'\n';}catch(const std::exception& error){std::ofstream(report)<<"FAIL after "<<checks<<": "<<error.what()<<'\n';}return 1;
}
} // namespace coincide
